// Bundles the framework-free offline capture page (src/offline/app.ts → public/offline/capture.js).
// Runs before `dev` and `build`. Output is generated; do not edit it by hand.
import { build } from "esbuild";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));
await build({
  entryPoints: [`${root}src/offline/app.ts`],
  outfile: `${root}public/offline/capture.js`,
  bundle: true,
  format: "esm",
  target: "es2022",
  minify: true,
  sourcemap: false,
  legalComments: "none",
  alias: { "@": `${root}src` },
  banner: { js: "/* PUIMS offline capture — generated by scripts/build-offline.mjs */" },
  logLevel: "warning",
});
console.log("built public/offline/capture.js");
